# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.91.0/ankra-cli-darwin-arm64"
      sha256 "cb422cda5b73c82d8a8a69bd749a1728e228098f5513c9947acd8ddf2bfe1074"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.91.0/ankra-cli-darwin-amd64"
      sha256 "c16ef6ab398d9fcf71fb61ed8396246d41070f070021f4027a6ae504a7bfe60b"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.91.0/ankra-cli-linux-arm64"
      sha256 "1fe46f1c864122ea72485cadc3ae8dc21b88a2afd0e6b9ea774eb2d7fd66fa11"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.91.0/ankra-cli-linux-amd64"
